{
  "component_id": "asset_discovery",
  "summary": "Identifies and prepares local, dependency-free assets for the browser task board app: seed task data and an asset manifest that downstream components can consume when building index.html, CSS, JavaScript, and tests.",
  "files": [
    {
      "path": "assets/seed-tasks.json",
      "content": "[
  {
    "id": "task-001",
    "title": "Plan board columns",
    "description": "Confirm the Todo, Doing, and Done workflow for the local task board.",
    "status": "todo",
    "priority": "high",
    "createdAt": "2026-06-27T09:00:00.000Z",
    "updatedAt": "2026-06-27T09:00:00.000Z"
  },
  {
    "id": "task-002",
    "title": "Wire localStorage persistence",
    "description": "Save task changes in the browser so the board survives refreshes.",
    "status": "doing",
    "priority": "high",
    "createdAt": "2026-06-27T09:10:00.000Z",
    "updatedAt": "2026-06-27T09:25:00.000Z"
  },
  {
    "id": "task-003",
    "title": "Add edit and delete workflows",
    "description": "Support changing task fields and safely removing tasks from the board.",
    "status": "todo",
    "priority": "medium",
    "createdAt": "2026-06-27T09:20:00.000Z",
    "updatedAt": "2026-06-27T09:20:00.000Z"
  },
  {
    "id": "task-004",
    "title": "Create local test script",
    "description": "Provide an npm test command that validates the generated browser app files locally.",
    "status": "done",
    "priority": "medium",
    "createdAt": "2026-06-27T09:30:00.000Z",
    "updatedAt": "2026-06-27T09:45:00.000Z"
  }
]
"
    },
    {
      "path": "assets/local-assets.json",
      "content": "{
  "assetSet": "local-task-board-assets",
  "version": "1.0.0",
  "createdFor": "local browser task board app",
  "runtime": {
    "requiresNetwork": false,
    "requiresBuildStep": false,
    "storage": "window.localStorage",
    "expectedEntryFile": "index.html"
  },
  "dataAssets": [
    {
      "id": "seed-tasks",
      "path": "assets/seed-tasks.json",
      "type": "application/json",
      "purpose": "Initial Todo/Doing/Done tasks used when localStorage has no saved board state.",
      "schema": {
        "root": "array",
        "requiredFields": [
          "id",
          "title",
          "description",
          "status",
          "priority",
          "createdAt",
          "updatedAt"
        ],
        "allowedStatuses": [
          "todo",
          "doing",
          "done"
        ],
        "allowedPriorities": [
          "low",
          "medium",
          "high"
        ]
      }
    }
  ],
  "uiAssetGuidance": {
    "css": {
      "recommendedFile": "style.css",
      "layout": "Three responsive columns labelled Todo, Doing, and Done.",
      "colors": {
        "pageBackground": "#f4f7fb",
        "panelBackground": "#ffffff",
        "primary": "#2563eb",
        "danger": "#dc2626",
        "text": "#172033",
        "mutedText": "#64748b"
      },
      "accessibility": [
        "Use visible focus states for form fields and buttons.",
        "Keep status controls labelled with their destination column.",
        "Use sufficient contrast for priority and action controls."
      ]
    },
    "javascript": {
      "recommendedFile": "script.js",
      "localStorageKey": "localTaskBoard.tasks.v1",
      "requiredWorkflows": [
        "load seed tasks when no localStorage value exists",
        "add a task to a selected status column",
        "edit title, description, status, and priority",
        "delete a task after user confirmation",
        "persist every mutation to localStorage",
        "render live task counts for Todo, Doing, and Done"
      ]
    },
    "html": {
      "recommendedFile": "index.html",
      "requiredLandmarks": [
        "main board region",
        "task form region",
        "Todo column",
        "Doing column",
        "Done column"
      ]
    }
  },
  "testAssetGuidance": {
    "recommendedPackageScript": "npm test",
    "minimumLocalChecks": [
      "index.html references style.css and script.js",
      "script.js contains the configured localStorage key",
      "all three statuses are represented",
      "seed task JSON is valid and includes Todo, Doing, and Done coverage"
    ]
  }
}
"
    }
  ],
  "public_contract": {
    "exports": [
      "assets/seed-tasks.json: JSON array of task objects with id, title, description, status, priority, createdAt, and updatedAt fields",
      "assets/local-assets.json: asset manifest describing the seed data, localStorage key, UI guidance, and minimum local test checks",
      "localStorage key for downstream JavaScript: localTaskBoard.tasks.v1",
      "allowed task statuses: todo, doing, done",
      "allowed task priorities: low, medium, high"
    ]
  },
  "manual_checks": [
    "Confirm assets/seed-tasks.json parses as valid JSON.",
    "Confirm seed tasks include at least one task in each board status: todo, doing, and done.",
    "Confirm assets/local-assets.json points to assets/seed-tasks.json and documents the localStorage key used by the app.",
    "Confirm no media-processing assets, video pipeline assets, or external network dependencies are introduced."
  ],
  "self_test": {
    "status": "pass",
    "checks": [
      "Generated only component-owned asset files under assets/.",
      "Seed data contains four realistic task board records.",
      "Seed data supports add/edit/delete workflows by defining mutable task fields and valid board statuses.",
      "Asset manifest provides downstream integration contracts for index.html, style.css, script.js, localStorage, and npm test checks."
    ]
  },
  "quality_gate": {
    "status": "pass",
    "reasons": [
      "No README or documentation-only delivery files were generated by this component.",
      "No duplicate paths exist in the provided prior manifest.",
      "Files are local, relative, text-based, and require no external services.",
      "The assets align with the raw user goal for a browser task board app and avoid the unrelated media workbench direction."
    ]
  }
}

